// Inline Embedded Object.
type EmbeddedObject struct {
	*openxml.CompositeElementBase
	XMLName     xml.Name           `xml:"http://schemas.openxmlformats.org/wordprocessingml/2006/main object"`
	DxaOriginal *types.StringValue `xml:"w:dxaOrig,attr,omitempty"`
	DyaOriginal *types.StringValue `xml:"w:dyaOrig,attr,omitempty"`
	Anchorid    *types.StringValue `xml:"w14:anchorId,attr,omitempty"`
	Drawing     *Drawing           `xml:"drawing,omitempty"`
	Control     *Control           `xml:"control,omitempty"`
	ObjectEmbed *ObjectEmbed       `xml:"objectEmbed,omitempty"`
	ObjectLink  *ObjectLink        `xml:"objectLink,omitempty"`
}

func NewEmbeddedObject() *EmbeddedObject {
	ret := &EmbeddedObject{}
	ns := openxml.NamespaceWordprocessingML
	ret.CompositeElementBase = openxml.NewCompositeElement(ns, "object", "w")
	return ret
}

func (m *EmbeddedObject) Clone() openxml.Element {
	ret := NewEmbeddedObject()
	if m.DxaOriginal != nil {
		v := *m.DxaOriginal
		ret.DxaOriginal = &v
	}
	if m.DyaOriginal != nil {
		v := *m.DyaOriginal
		ret.DyaOriginal = &v
	}
	if m.Anchorid != nil {
		v := *m.Anchorid
		ret.Anchorid = &v
	}
	if m.Drawing != nil {
		ret.Drawing = m.Drawing.Clone().(*Drawing)
	}
	if m.Control != nil {
		ret.Control = m.Control.Clone().(*Control)
	}
	if m.ObjectEmbed != nil {
		ret.ObjectEmbed = m.ObjectEmbed.Clone().(*ObjectEmbed)
	}
	if m.ObjectLink != nil {
		ret.ObjectLink = m.ObjectLink.Clone().(*ObjectLink)
	}
	return ret
}

func (m *EmbeddedObject) Validate() error {
	if m.Control != nil {
		if err := m.Control.Validate(); err != nil {
			return err
		}
	}
	if m.ObjectEmbed != nil {
		if err := m.ObjectEmbed.Validate(); err != nil {
			return err
		}
	}
	if m.ObjectLink != nil {
		if err := m.ObjectLink.Validate(); err != nil {
			return err
		}
	}
	return nil
}

